from docx import Document

doc = Document('/root/offer_letter_filled.docx')

print("=== VERIFICATION: Sample of filled document ===\n")

# Show first 5 paragraphs
for i, para in enumerate(doc.paragraphs[:5]):
    if para.text.strip():
        print(f"Paragraph {i}: {para.text[:100]}")

print("\n=== Checking for unfilled placeholders ===")
unfilled = []
for para in doc.paragraphs:
    if '{{' in para.text and '}}' in para.text:
        unfilled.append(para.text)

if unfilled:
    print(f"Found {len(unfilled)} unfilled placeholders:")
    for item in unfilled[:5]:
        print(f"  - {item[:80]}")
else:
    print("✓ No unfilled placeholders found")

print("\n=== Checking for conditional markers ===")
has_markers = False
for para in doc.paragraphs:
    if '{{IF_' in para.text or '{{END_IF_' in para.text:
        has_markers = True
        print(f"  - {para.text[:80]}")

if not has_markers:
    print("✓ No leftover conditional markers found")

print("\n=== Sample content ===")
# Find a paragraph with actual content
for para in doc.paragraphs:
    if len(para.text.strip()) > 20 and '{{' not in para.text:
        print(para.text)
        break

EOF
